// ==========================================================================
// CONFIGURACIÓN DE TUS IMÁGENES Y NARRACIÓN EN OFF
// ==========================================================================

// 1. CARPETA DONDE ESTÁN TUS IMÁGENES:
// Coloca tus fotos (ej. 1.jpg, 2.jpg, ... o foto1.png, etc.) en esta carpeta.
const carpetaImagenes = '/media/susej/C06E72656E72545E/Users/PC/Desktop/creador_videos/imagenes_para_video';

// 2. LISTA DE IMÁGENES A USAR (OPCIONAL):
// - Si dejas [] (vacío), tomará automáticamente TODAS las imágenes de la carpeta en orden numérico/alfabético.
// - O puedes especificar los nombres exactos: ['1.jpg', '2.jpg', '3.jpg']
const imagenes = [];

// 3. TEXTO DE LA NARRACIÓN EN OFF (TIENES 2 OPCIONES):
// - OPCIÓN A: Pega directamente aquí tu narración como texto normal.
// - OPCIÓN B: Déjalo vacío ('') y guarda un archivo 'narracion.txt' en tu carpeta de imágenes.
const textoNarracion = `Tres misterios ancestrales que la ciencia moderna aún no ha podido resolver. El último de ellos cambiará para siempre todo lo que creías saber sobre nuestro pasado.`;

// 4. VOZ MASCULINA EN ESPAÑOL LATINOAMERICANO (100% Gratuita):
// - 'es-MX-JorgeNeural'   -> México (Estilo Narrador Documental / YouTube Shorts - Recomendada)
// - 'es-CO-GonzaloNeural' -> Colombia (Cálida y neutral)
// - 'es-AR-TomasNeural'   -> Argentina
// - 'es-PE-AlexNeural'    -> Perú
const voz = 'es-MX-JorgeNeural';

// 5. TRANSICIONES Y ESTILO VISUAL:
// - 'dissolve' (desvanecimiento cruzado suave entre imágenes)
// - 'fade' (fundido suave)
// - 'wipeleft' / 'wiperight' / 'slideup' / 'circlecrop'
const transicion = 'dissolve';
const duracionTransicionSegundos = 0.6;

// 6. SUBTÍTULOS LLAMATIVOS (ROJO Y NEGRO / DOCUMENTAL):
// true = quema subtítulos cinematográficos con palabras clave en Rojo Intenso y borde negro grueso (sin verdes ni amarillos).
const subtitulos = true;
const estiloSubtitulos = 'documental';

return [{
  json: {
    accion: 'imagenes_narracion',
    carpeta_imagenes: carpetaImagenes,
    imagenes: imagenes,
    texto_narracion: textoNarracion,
    voz: voz,
    transicion: transicion,
    duracion_transicion_segundos: duracionTransicionSegundos,
    subtitulos: subtitulos,
    estilo_subtitulos: estiloSubtitulos
  }
}];

const videoInfo = $('Crear Video (FFmpeg + Voz Latina + Ken Burns)').first().json;
const aiRaw = $input.first().json.output || $input.first().json.text || '';

let copyData = {};
try {
  const match = aiRaw.match(/\{[\s\S]*\}/);
  copyData = JSON.parse(match ? match[0] : aiRaw);
} catch (e) {
  copyData = {
    titulo_gancho: 'MISTERIOS QUE LA CIENCIA NO EXPLICA',
    descripcion: 'Descubre los enigmas más impactantes que desafían la lógica moderna.',
    cta: '¿Cuál te sorprendió más? Comenta y síguenos para más contenido fascinante.',
    hashtags: ['#misterio', '#curiosidades', '#shorts', '#viral']
  };
}

return [{
  json: {
    status: '🎉 ¡Video con imágenes animadas, transiciones y voz latina generado con éxito!',
    archivo_final: videoInfo.video_final_path || videoInfo.video_path || '/media/susej/C06E72656E72545E/Users/PC/Desktop/creador_videos/videos_listos/video_narrado_final.mp4',
    duracion_segundos: videoInfo.duracion_segundos || 0,
    total_imagenes_animadas: videoInfo.total_imagenes || 0,
    voz_narrador: videoInfo.voz_utilizada || 'es-MX-JorgeNeural (Masculina Latina)',
    transicion_utilizada: videoInfo.transicion_utilizada || 'dissolve',
    subtitulos_incluidos: videoInfo.subtitulos_incluidos !== false,
    copy_para_redes: {
      titulo_gancho: copyData.titulo_gancho,
      descripcion: copyData.descripcion,
      cta: copyData.cta,
      hashtags: copyData.hashtags || []
    },
    carpeta_en_tu_pc: 'creador_videos/videos_listos/'
  }
}];
